<?php
function staff_filters($filter,$destination){$f=$filter['values']; ?>
<form method="get" class="panel staff-filters"><input type="hidden" name="page" value="<?=e($destination)?>"><div class="staff-filter-grid">
<label>Reported from<input type="date" name="from" value="<?=e($f['from']??'')?>"></label><label>Reported to<input type="date" name="to" value="<?=e($f['to']??'')?>"></label>
<label>Category<select name="category"><option value="">All categories</option><?php foreach(categories() as $c):?><option value="<?=$c['id']?>" <?=$f['category']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label>
<label>Area<select name="area"><option value="">All areas</option><?php foreach(service_areas() as $a):?><option value="<?=$a['id']?>" <?=$f['area']==$a['id']?'selected':''?>><?=e($a['name'])?></option><?php endforeach;?></select></label>
<label>Status<select name="status"><option value="">All statuses</option><?php foreach(staff_statuses() as $status):?><option <?=$f['status']===$status?'selected':''?>><?=$status?></option><?php endforeach;?></select></label>
<label>Priority<select name="priority"><option value="">All priorities</option><?php foreach(['High','Medium','Low'] as $v):?><option <?=$f['priority']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label>
<?php if(user()['role']==='admin'):?><label>Officer<select name="officer"><option value="">All officers</option><?php foreach(q("SELECT id,name,active FROM users WHERE role='officer' ORDER BY name")->fetchAll() as $o):?><option value="<?=$o['id']?>" <?=$f['officer']==$o['id']?'selected':''?>><?=e($o['name'])?><?=$o['active']?'':' (disabled)'?></option><?php endforeach;?></select></label><?php endif;?>
<label>Maintenance team<select name="team"><option value="">All teams</option><?php foreach(q("SELECT id,name,active FROM users WHERE role='maintenance' ORDER BY name")->fetchAll() as $team):?><option value="<?=$team['id']?>" <?=$f['team']==$team['id']?'selected':''?>><?=e($team['name'])?><?=$team['active']?'':' (disabled)'?></option><?php endforeach;?></select></label><label>Team stage<select name="team_stage"><option value="">All stages</option><?php foreach(['none'=>'No team assigned','Assigned'=>'Assigned to team','In Progress'=>'Team working','Returned'=>'Returned to team','Review'=>'Officer review needed','Approved'=>'Officer approved'] as $key=>$label):?><option value="<?=e($key)?>" <?=$f['team_stage']===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label>
<label>Work queue<select name="view"><?php foreach(['all'=>'All work','unassigned'=>'Unassigned','overdue'=>'Overdue','high'=>'High priority','approval'=>'Awaiting approval'] as $v=>$label):if($v==='unassigned'&&user()['role']==='officer')continue;?><option value="<?=$v?>" <?=$f['view']===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></label>
<label>Sort by<select name="sort"><?php foreach(['priority'=>'Priority, oldest first','due'=>'Due date','oldest'=>'Oldest first','newest'=>'Newest first'] as $v=>$label):?><option value="<?=$v?>" <?=$f['sort']===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></label></div><?php geo_filter_controls($f);?><div class="row"><button class="button secondary">Apply filters</button><a class="text-link" href="index.php?page=<?=e($destination)?>">Reset</a><span class="small muted">Dates refer to when a report was submitted.</span></div></form>
<?php }
function staff_table($rows){if(user()['role']==='admin'){admin_report_table($rows);return;}if(user()['role']==='officer'){officer_table($rows);return;}if(!$rows){empty_state('No work matches these filters.');return;}?><div class="table-wrap"><table><thead><tr><th>Report / area</th><th>Priority</th><th>Status</th><th>Officer</th><th>Due / attention date</th></tr></thead><tbody><?php foreach($rows as $i):$closed=in_array($i['status'],['Resolved','Rejected','Duplicate'],true);$deadline=$i['due_date']?:date('Y-m-d',strtotime($i['created_at'].' +7 days'));$overdue=!$closed&&($i['due_date']?strtotime($deadline.' 23:59:59')<time():strtotime($i['created_at'])<time()-7*86400);?><tr><td><a class="table-title" href="index.php?page=issue&amp;id=<?=$i['id']?>"><small>#<?=$i['id']?></small><?=e($i['title'])?></a><small class="muted"><?=e($i['area_name']?:'Area not specified')?> · <?=e($i['category'])?></small></td><td><span class="priority-chip p-<?=strtolower($i['priority'])?>"><?=e($i['priority'])?></span></td><td><?=badge($i['status'])?></td><td><?=e($i['officer']?:'Unassigned')?><?php if($i['maintenance_id']):?><small class="muted">Team: <?=e($i['maintenance_team']?:'Unavailable')?> · <?=e($i['maintenance_stage']==='Review'?'Officer review needed':$i['maintenance_stage'])?></small><?php endif;?></td><td><?=e($deadline)?><?php if(!$i['due_date']):?><small class="muted"> · default</small><?php endif;?><?php if($overdue):?><small class="overdue-label">Overdue</small><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php }
function staff_update_panel($i,$admin){
 if(!$admin && !in_array($i['status'],['Assigned','In Progress','Awaiting Approval'],true))return;
?><section class="panel"><div class="eyebrow"><?=$admin?'ADMIN WORKSPACE':'OFFICER WORKSPACE'?></div><h3><?=$admin&&$i['status']==='Awaiting Approval'?'Review completion':'Update this report'?></h3>
<?php if($i['status']==='Awaiting Approval'):?><div class="alert">Completion is waiting for Province Admin final approval. Only approval marks it Resolved.</div><?php endif;?>
<form method="post" enctype="multipart/form-data"><?php csrf();?><input type="hidden" name="action" value="update_issue"><input type="hidden" name="previous_revision" value="<?=e(assignment_revision($i))?>"><input type="hidden" name="issue_id" value="<?=$i['id']?>">
<label>Status / decision<select name="status"><?php $options=array_merge([$i['status']],staff_transitions($i['status'],$admin));$options=array_values(array_filter($options,function($v)use($i){return $v===$i['status'] || !in_array($v,['In Progress','Awaiting Approval'],true) || ($i['status']==='Awaiting Approval'&&$v==='In Progress');}));if($admin)$options=array_values(array_filter($options,function($status)use($i){return $status!=='Assigned' || $i['status']==='Assigned';}));foreach($options as $v):?><option value="<?=$v?>"><?=e($v)?><?=$v==='Awaiting Approval'&&$i['status']==='In Progress'?' — submit completion':($v==='Resolved'&&$i['status']==='Awaiting Approval'?' — approve completion':($v==='In Progress'&&$i['status']==='Awaiting Approval'?' — return to District Officer for review':''))?></option><?php endforeach;?></select></label>
<?php if($admin):?><label>Service area<select id="assignment-area" name="area_id"><option value="">Not specified</option><?php foreach(service_areas() as $a):?><option value="<?=$a['id']?>" <?=$i['area_id']==$a['id']?'selected':''?>><?=e($a['name'])?></option><?php endforeach;?></select></label>
<div class="section-space"><p class="small muted">Current officer: <strong><?=e($i['officer']?:'Unassigned')?></strong></p><?php if(in_array($i['status'],['Verified','Assigned','In Progress'],true)):?><a class="button secondary" href="index.php?page=assignments&amp;view=<?=$i['officer_id']?'assigned':'unassigned'?>&amp;id=<?=$i['id']?>#assignment"><?=$i['officer_id']?'Manage assignment':'Assign this issue'?> →</a><?php elseif($i['status']==='Submitted'):?><p class="small muted">Mark this report Verified, then open Assign issues to select an officer.</p><?php endif;?></div>
<label>Priority<select name="priority"><?php foreach(['Low','Medium','High'] as $v):?><option <?=$i['priority']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Due date (optional)<input type="date" name="due_date" value="<?=e($i['due_date']??'')?>"></label><p class="small muted">Without a due date, open work is flagged after 7 days.</p><?php endif;?>
<label><?=$i['status']==='Awaiting Approval'&&$admin?'Review decision / reason':'Update note'?><textarea name="note" rows="3" minlength="3" maxlength="2000" required></textarea></label>
<?php if(in_array($i['status'],['In Progress','Awaiting Approval'],true)):?><label>Completion photo<input type="file" name="resolution_photo" accept="image/jpeg,image/png,image/webp" data-preview="completion-preview"></label><img id="completion-preview" class="upload-preview" alt="Selected completion evidence" hidden><p class="small muted">A new photo is required when submitting work for approval. Approving existing evidence does not require another upload.</p><?php endif;?>
<button class="button full"><?=$admin&&$i['status']==='Awaiting Approval'?'Save review decision':'Save update'?></button></form></section>
<?php if(in_array($i['status'],['Assigned','In Progress','Awaiting Approval'],true)):?><section class="panel"><h3>Add progress evidence</h3><form method="post" enctype="multipart/form-data"><?php csrf();?><input type="hidden" name="action" value="progress_photo"><input type="hidden" name="issue_id" value="<?=$i['id']?>"><label>Progress note<textarea name="progress_note" minlength="3" maxlength="2000" rows="3" required></textarea></label><label>Progress photo<input type="file" name="progress_photo" accept="image/jpeg,image/png,image/webp" data-preview="progress-preview" required></label><img id="progress-preview" class="upload-preview" alt="Selected progress photo" hidden><button class="button secondary">Upload progress photo</button></form></section><?php endif;?>
<?php }
function progress_gallery($id){$photos=q('SELECT p.*,u.name FROM issue_progress_photos p JOIN users u ON u.id=p.user_id WHERE issue_id=? ORDER BY p.id DESC',[$id])->fetchAll();if(!$photos)return;?><section class="panel section-space"><h2>Work photos & evidence</h2><div class="work-photo-grid"><?php foreach($photos as $photo):?><article><a href="media.php?file=<?=e($photo['filename'])?>" target="_blank" rel="noopener"><img src="media.php?file=<?=e($photo['filename'])?>" alt="<?=e($photo['phase'])?> evidence" loading="lazy"></a><strong><?=e(ucfirst($photo['phase']))?></strong><p class="small preline"><?=e($photo['note'])?></p><small class="muted"><?=e($photo['name'])?> · <?=e($photo['created_at'])?></small></article><?php endforeach;?></div></section><?php }
